INSERT INTO `v1_d93f9032d69e71e2ac1568d1a2131d13fa795b31bd7e189cc2b494fbdbc6d6a7` VALUES (1, 2, "vo_minigame_1013_icon_2_002_001", "訓練はまだ\nここからですわ", 3000, 2, 1000, 2, "調子が上がって\nきたなっ", "vo_minigame_1013_icon_1_002_001");
INSERT INTO `v1_d93f9032d69e71e2ac1568d1a2131d13fa795b31bd7e189cc2b494fbdbc6d6a7` VALUES (2, 2, "vo_minigame_1013_icon_2_003_001", "クスクス、悪くない\n流れですわね", 3000, 2, 5000, 2, "ほらほら、\nまだいけるだろ？", "vo_minigame_1013_icon_1_003_001");
INSERT INTO `v1_d93f9032d69e71e2ac1568d1a2131d13fa795b31bd7e189cc2b494fbdbc6d6a7` VALUES (3, 2, "vo_minigame_1013_icon_2_004_001", "すばらしい\n記録ですわ", 3000, 2, 10000, 3, "へへっ、おまえら\nやるじゃねえか！", "vo_minigame_1013_icon_1_004_001");
INSERT INTO `v1_d93f9032d69e71e2ac1568d1a2131d13fa795b31bd7e189cc2b494fbdbc6d6a7` VALUES (4, 2, "vo_minigame_1013_icon_2_005_001", "乗りに乗って\nいますわね", 3000, 3, 10000, 3, "あたしたちはまだ\n止まらねえぜ！", "vo_minigame_1013_icon_1_005_001");
INSERT INTO `v1_d93f9032d69e71e2ac1568d1a2131d13fa795b31bd7e189cc2b494fbdbc6d6a7` VALUES (5, 2, "vo_minigame_1013_icon_2_005_002", "まだまだ行きます\nついてきなさい", 3000, 3, 10000, 3, "見てろよ！\nマコト班の快進撃だ！", "vo_minigame_1013_icon_1_005_002");
INSERT INTO `v1_d93f9032d69e71e2ac1568d1a2131d13fa795b31bd7e189cc2b494fbdbc6d6a7` VALUES (6, 2, "vo_minigame_1013_icon_2_005_003", "エリコ班の\n本領発揮ですわ！", 3000, 3, 10000, 3, "うおぉぉっ！\n絶好調だぜ！", "vo_minigame_1013_icon_1_005_003");
INSERT INTO `v1_d93f9032d69e71e2ac1568d1a2131d13fa795b31bd7e189cc2b494fbdbc6d6a7` VALUES (7, 2, "vo_minigame_1013_icon_2_006_001", "ここからは\n前人未到の領域です！", 3000, 4, 0, 3, "どこまで行けるか\n楽しみだなっ！", "vo_minigame_1013_icon_1_006_001");
INSERT INTO `v1_d93f9032d69e71e2ac1568d1a2131d13fa795b31bd7e189cc2b494fbdbc6d6a7` VALUES (8, 3, "vo_minigame_1013_icon_2_007_001", "厄介でしたわ…", 1000, 5, 1, 4, "まだ諦めんなよっ", "vo_minigame_1013_icon_1_007_001");
INSERT INTO `v1_d93f9032d69e71e2ac1568d1a2131d13fa795b31bd7e189cc2b494fbdbc6d6a7` VALUES (9, 3, "vo_minigame_1013_icon_2_007_002", "油断大敵です", 1000, 5, 1, 4, "冷やっとしたぜ…！", "vo_minigame_1013_icon_1_007_002");
INSERT INTO `v1_d93f9032d69e71e2ac1568d1a2131d13fa795b31bd7e189cc2b494fbdbc6d6a7` VALUES (10, 3, "vo_minigame_1013_icon_2_007_003", "忌々しいっ…", 1000, 5, 1, 4, "弱音を吐くなっ", "vo_minigame_1013_icon_1_007_003");
INSERT INTO `v1_d93f9032d69e71e2ac1568d1a2131d13fa795b31bd7e189cc2b494fbdbc6d6a7` VALUES (11, 4, "vo_minigame_1013_icon_2_008_001", "大所帯ですわね", 1500, 6, 99, 3, "マコト班集合！", "vo_minigame_1013_icon_1_008_001");
INSERT INTO `v1_d93f9032d69e71e2ac1568d1a2131d13fa795b31bd7e189cc2b494fbdbc6d6a7` VALUES (12, 4, "vo_minigame_1013_icon_2_008_002", "エリコ班へようこそ", 1500, 6, 99, 3, "連携してくぞ！", "vo_minigame_1013_icon_1_008_002");
INSERT INTO `v1_d93f9032d69e71e2ac1568d1a2131d13fa795b31bd7e189cc2b494fbdbc6d6a7` VALUES (13, 1, "vo_minigame_1013_icon_2_020_001", "ナナカちゃんに\nお任せあれ", 3000, 8, 0, 6, "みんなに力を！", "vo_minigame_1013_icon_1_020_001");
INSERT INTO `v1_d93f9032d69e71e2ac1568d1a2131d13fa795b31bd7e189cc2b494fbdbc6d6a7` VALUES (14, 1, "vo_minigame_1013_icon_2_022_001", "はっはっは！\n任せろ！", 3000, 9, 0, 7, "任せてくれたまえ", "vo_minigame_1013_icon_1_022_001");
INSERT INTO `v1_d93f9032d69e71e2ac1568d1a2131d13fa795b31bd7e189cc2b494fbdbc6d6a7` VALUES (15, 1, "vo_minigame_1013_icon_2_023_001", "どんどんいくわよ", 3000, 10, 0, 8, "ほな、いきまひょか", "vo_minigame_1013_icon_1_023_001");
